@page "/chat"
@namespace sv_5d2b405122e34243adac1dc021eb5c61.Components.Pages.Chat
@rendermode InteractiveServer
@using sv_5d2b405122e34243adac1dc021eb5c61.Services
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="main-content @(threadOpen ? "with-thread" : "")">
        <MessageArea CurrentChannel="CurrentChannel"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadOlderMessages="LoadOlderMessages" />

        @if (threadOpen)
        {
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    </div>
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> threadReplyCounts = new();
    private Message? threadRootMessage;

    private int selectedChannelId;
    private bool threadOpen;
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    private Channel? CurrentChannel => channels.FirstOrDefault(c => c.Id == selectedChannelId);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        threadReplyCounts = await BuildThreadReplyCounts();
        CloseThread();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        messageSkip += PageSize;
        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            var newCounts = await BuildThreadReplyCounts();
            foreach (var kv in newCounts)
            {
                threadReplyCounts[kv.Key] = kv.Value;
            }
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootMessage.Id] =
            threadReplyCounts.GetValueOrDefault(threadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reaction
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messageSkip + PageSize);
    }

    private async Task<Dictionary<int, int>> BuildThreadReplyCounts()
    {
        var counts = new Dictionary<int, int>();
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id);

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                counts[rootId] = thread.Count;
            }
        }
        return counts;
    }
}

